// Lösungswege und Begründungen je Fall (id → k: Anfang der richtigen Antwort, w: Schritte, o: Begründung je Option)
window.WPR_LOES = Object.assign(window.WPR_LOES || {}, {"fb-9-prod": {"k": "1, 3 und 4", "w": ["Zwei Anspruchsgrundlagen gegen den Hersteller trennen: ProdHaftG (verschuldensunabhängig) und § 823 I (Produzentenhaftung mit Beweislastumkehr).", "ProdHaftG: Fehler (Fabrikation) → Haftung auch für „Ausreißer“. Personenschaden voll ersatzfähig. Sachschaden nur an anderen, privat genutzten Sachen, mit 500 € Selbstbeteiligung (§ 11); das fehlerhafte Produkt selbst (E-Bike) nie (§ 1 I 2).", "§ 823 I: Bei Ausreißern kann sich der Hersteller entlasten, weil ihn kein Verschulden trifft.", "Daraus folgen die Aussagen 1, 3 und 4."], "o": [null, null, null, null, null, null]}, "fb-1-tier": {"k": "R muss die 3.000 €", "w": ["Anspruch: § 823 I – Verletzung des Eigentums an einem Tier (Sachvorschriften gelten entsprechend, § 90a S. 3).", "Umfang: Geld für die Herstellung (§ 249 II). Grenze § 251 II 1: Bei unverhältnismäßigen Herstellungskosten nur Wertersatz.", "Sonderregel § 251 II 2: Heilbehandlungskosten für ein Tier sind nicht schon deshalb unverhältnismäßig, weil sie den Tierwert erheblich übersteigen. Maßstab: Was ein verständiger Tierhalter aufwenden würde.", "Ergebnis: R muss die 3.000 € grundsätzlich voll tragen."], "o": [null, null, null, null, null, null]}, "fb-2-we2": {"k": "B hat keinen Anspr", "w": ["Vertraglicher Anspruch (§ 662, § 280 I)? Setzt Rechtsbindungswillen voraus. „Mal nach dem Briefkasten schauen“ unter Nachbarn ist eine Alltagsgefälligkeit ohne Rechtsbindung – N wusste nicht einmal von der Frist.", "Ohne Schuldverhältnis auch keine Haftungsmilderung (§ 277) und kein Mitverschulden zu prüfen; c.i.c. scheidet mangels geschäftlichen Kontakts aus.", "Delikt (§ 823 I)? B hat einen reinen Vermögensschaden (Fristversäumnis); die Briefe wurden nicht beschädigt. Das Vermögen ist kein geschütztes Rechtsgut.", "Ergebnis: kein Anspruch."], "o": [null, null, null, null, null, null]}, "rh6-13": {"k": "F kann von R Schme", "w": ["Vertrag? Noch keiner – F hatte noch nicht bestellt.", "Vorvertragliches Schuldverhältnis (§ 311 II Nr. 2): Wer ein Restaurant betritt, um zu essen, ist in der Vertragsanbahnung → Schutzpflichten für ihre Rechtsgüter (§ 241 II).", "Pflichtverletzung: herausragender Nagel. Das Verschulden des Schreiners S, der den Stuhl repariert hat, wird R über § 278 zugerechnet.", "Anspruch aus §§ 280 I, 311 II Nr. 2, 241 II – einschließlich Schmerzensgeld (§ 253 II gilt für alle Anspruchsgrundlagen)."], "o": [null, null, null, null, null, null]}, "rh6-14": {"k": "U hat gegen S eine", "w": ["Grundsatz: Bis zum Vertragsschluss darf jeder Verhandlungen abbrechen (Abschlussfreiheit).", "Ausnahme c.i.c. (§§ 280 I, 311 II Nr. 1, 241 II): Wer in zurechenbarer Weise das Vertrauen erweckt, der Vertrag komme sicher zustande, und dann ohne triftigen Grund abbricht, haftet.", "Rechtsfolge: negatives Interesse – U wird so gestellt, als hätte er nicht vertraut → Kreditzinsen. Kein Anspruch auf Vertragsschluss, kein entgangener Gewinn.", "§ 823 I scheidet aus: reiner Vermögensschaden."], "o": [null, null, null, null, null, null]}, "rh6-32": {"k": "K muss das Caterin", "w": ["Buffet für die Feier an genau diesem Tag → absolutes Fixgeschäft. Geliefert wurde nicht vegan → nicht das Geschuldete (§ 434 II bzw. aliud).", "Nacherfüllung ist am selben Tag nicht mehr möglich (Feier) → Leistung unmöglich → K muss nicht zahlen (§ 326 I).", "Teppich: M haftet selbst aus § 823 I (Eigentum). C haftet vertraglich über §§ 280 I, 241 II, 278 – ohne Entlastungsmöglichkeit."], "o": [null, null, null, null, null, null]}, "V-20": {"k": "Produzentenhaftung", "w": ["Produzentenhaftung nach § 823 I: Verletzungshandlung ist das Inverkehrbringen eines fehlerhaften Produkts (hier Fabrikationsfehler).", "Rechtsgutsverletzung: Körper/Gesundheit der K; Kausalität.", "Verschulden: Beweislastumkehr – liegt der Fehler im Herstellerbereich, muss H beweisen, dass ihn kein Verschulden trifft.", "Rechtsfolge: Schadensersatz inkl. Schmerzensgeld (§ 253 II). Daneben ProdHaftG (§ 15 II)."], "o": [null, null, null, null, null, null]}, "rh6-41": {"k": "Ja, B kann Kranken", "w": ["§ 823 I: Rechtsgutsverletzungen Körper (Nasenbein) und Eigentum (Brille) durch einen vorsätzlichen Faustschlag; kausal, rechtswidrig, schuldhaft.", "Keine Einwilligung: Wer sich auf einen verbalen Streit einlässt, willigt nicht in Schläge ein. Kein Mitverschulden für einen vorsätzlichen Angriff.", "Umfang: Heilungskosten und Brille (§ 249), dazu Schmerzensgeld (§ 253 II) – ohne Dauerschaden."], "o": [null, null, null, null, null, null]}, "rh6-42": {"k": "Der Verrichtungsge", "w": ["§ 831: eigene Anspruchsgrundlage gegen den Geschäftsherrn für vermutetes Auswahl- und Überwachungsverschulden – mit Entlastungsmöglichkeit (I 2).", "Verrichtungsgehilfe ist, wer weisungsgebunden in den Organisationsbereich des Geschäftsherrn eingegliedert ist. Selbstständige sind es mangels Weisungsgebundenheit nicht.", "§ 278 ist nur Zurechnungsnorm in einem bestehenden Schuldverhältnis – ohne Entlastung."], "o": [null, null, null, null, null, null]}, "rh6-43": {"k": "U muss K Schadense", "w": ["Haftung des V selbst: § 823 I (Körperverletzung durch fahrlässiges Hantieren).", "Haftung des U: § 831 I 1 – V ist als Angestellter weisungsgebunden (Verrichtungsgehilfe) und hat in Ausführung der Verrichtung widerrechtlich geschädigt.", "Entlastung (§ 831 I 2) scheitert: U kontrolliert praktisch nie, obwohl V schon mehrfach ungeschickt war – keine sorgfältige Überwachung.", "Rechtsfolge: Schadensersatz einschließlich Schmerzensgeld (§ 253 II)."], "o": [null, null, null, null, null, null]}, "rh6-45": {"k": "P hat keine vertra", "w": ["Zwischen dem zufälligen Passanten P und A, B (und G) besteht kein Vertrag, kein vorvertragliches Verhältnis, und P steht nicht in Leistungsnähe (kein Vertrag mit Schutzwirkung).", "Also nur Delikt: A und B haften selbst aus § 823 I; G haftet aus § 831 I (Verrichtungsgehilfen), sofern er sich nicht entlasten kann.", "„Ein paar Bierchen“ heben die Deliktsfähigkeit nicht auf (§ 827)."], "o": [null, null, null, null, null, null]}, "rh6-46": {"k": "Liegen die Vorauss", "w": ["Ansprüche gegen den Hersteller H: § 1 ProdHaftG und § 823 I (Produzentenhaftung) bestehen nebeneinander (§ 15 II ProdHaftG).", "ProdHaftG: Das fehlerhafte Produkt selbst (Auto) ist nicht ersatzfähig; für andere privat genutzte Sachen (Garagentor) mit 500 € Selbstbeteiligung (§ 11).", "§ 823 I: Beweislastumkehr beim Verschulden, aber keine Selbstbeteiligung und keine Haftungshöchstgrenze.", "Gegen den Händler V nur vertraglich; deliktisch fehlt ihm eine eigene Pflichtverletzung."], "o": [null, null, null, null, null, null]}, "rh6-49": {"k": "G kann Eigentümer ", "w": ["Schuldrecht wirkt nur relativ: Der Kaufvertrag mit K bindet E, nicht G. Ein Doppelverkauf ist wirksam.", "Eigentum an Grundstücken geht über durch Auflassung und Eintragung (§§ 873 I, 925). E ist Berechtigter → G kann Eigentümer werden.", "K bleibt nur gegen E: Unmöglichkeit der Übereignung (§ 275 I) → Schadensersatz (§§ 280 I, III, 283). Gegen G hat er nichts."], "o": [null, null, null, null, null, null]}, "P2-del-10": {"k": "400 € (900 € abzüg", "w": ["ProdHaftG: Fehlerhaftes Produkt (Konstruktionsfehler), Schaden an einer anderen Sache (Tisch), die privat genutzt wird → ersatzfähig.", "Nicht ersatzfähig: das fehlerhafte Produkt selbst (Wasserkocher, § 1 I 2).", "Selbstbeteiligung bei Sachschäden: 500 € (§ 11) → 900 € − 500 € = 400 €. Verschulden ist nicht erforderlich; ein Vertrag mit H auch nicht."], "o": [null, null, null, null, null, null]}, "P2-del-11": {"k": "F hat einen Anspru", "w": ["Zwei Haftungswege gegen den Hersteller: § 823 I (Produzentenhaftung) und ProdHaftG.", "§ 823 I: Verschulden wird vermutet, H kann sich aber entlasten – bei einem trotz aller zumutbaren Kontrollen unerkennbaren „Ausreißer“ gelingt das.", "ProdHaftG: verschuldensunabhängig, erfasst gerade auch Ausreißer → F hat einen Anspruch (Personenschaden)."], "o": [null, null, null, null, null, null]}, "P2-del-12": {"k": "B muss 10.000 € za", "w": ["Mehrere Verantwortliche für denselben Schaden haften als Gesamtschuldner (§ 840 I).", "Außenverhältnis (§ 421): F kann von jedem den ganzen Betrag verlangen, insgesamt aber nur einmal → B muss 10.000 € zahlen.", "Innenverhältnis (§ 426): Ausgleich nach Verantwortungsanteilen → B kann von A 7.000 € zurückverlangen."], "o": [null, null, null, null, null, null]}, "P2-del-13": {"k": "F bekommt die Hälf", "w": ["A haftet aus § 823 I (Körperverletzung durch fahrlässig zu schnelles Fahren), daneben § 7 StVG.", "Mitverschulden (§ 254 I): Hat der Geschädigte bei der Entstehung des Schadens mitgewirkt, hängt der Ersatz von der Abwägung der Verursachungsanteile ab. F ging bei Rot.", "Das Gericht wertet 50 : 50 → F bekommt die Hälfte aller Schadensposten, auch beim Schmerzensgeld. Kein vollständiger Ausschluss."], "o": [null, null, "§ 254 kürzt alle Schadensposten nach derselben Quote, auch das Schmerzensgeld. Es wird nicht gestrichen, sondern halbiert bzw. bei der Bemessung berücksichtigt.", null, "Hat A selbst einen Schaden, würde auch sein Anspruch gegen F nach § 254 gekürzt. Eine Aufrechnung „in voller Höhe“ gibt es nicht.", null]}, "P2-del-14": {"k": "E bekommt nichts, ", "w": ["H hat E vorsätzlich verletzt → § 823 I erfüllt, wenn H rechtswidrig handelte.", "Notwehr (§ 227): gegenwärtiger, rechtswidriger Angriff eines Menschen (E kommt mit Messer auf ihn zu) und erforderliche Verteidigung. Der Schlag ist das mildeste sichere Mittel in dieser Lage.", "Gerechtfertigtes Handeln ist nicht rechtswidrig → kein Schadensersatz, kein Schmerzensgeld. Defensivnotstand (§ 228) passt nur bei Gefahren durch Sachen oder Tiere."], "o": [null, null, null, "Eine Teilung gibt es nur bei § 254, wenn beide Seiten rechtswidrig zum Schaden beigetragen haben. H handelte gerechtfertigt – er schuldet nichts.", null, null]}, "P2-del-15": {"k": "§ 823 I (allgemein", "w": ["Welche Rechtsgüter sind betroffen? Nicht Eigentum, sondern Ehre und Ansehen des U → allgemeines Persönlichkeitsrecht als „sonstiges Recht“ im Sinne des § 823 I.", "Daneben Schutzgesetzverletzung: Üble Nachrede (§ 186 StGB) schützt gerade den Einzelnen → § 823 II i. V. m. § 186 StGB.", "Erfundene Tatsachenbehauptungen sind von der Pressefreiheit nicht gedeckt. Neben Gegendarstellung und Unterlassung besteht Schadensersatz."], "o": [null, null, "§ 812 betrifft ungerechtfertigte Vermögensverschiebungen. Hier geht es um eine rechtswidrige Verletzung von Persönlichkeit und Ansehen – Delikt.", "Die Gegendarstellung ist nur ein zusätzlicher presserechtlicher Anspruch. Daneben kann U Unterlassung und Schadensersatz verlangen.", null, null]}, "P2-del-16": {"k": "4.000 € netto; Ums", "w": ["Anspruch: § 823 I (Eigentum am Wagen). Umfang: § 249.", "§ 249 II 1: Bei Sachbeschädigung kann der Geschädigte statt der Herstellung den dafür erforderlichen Geldbetrag verlangen – auch ohne zu reparieren (fiktive Abrechnung).", "§ 249 II 2: Umsatzsteuer nur, wenn und soweit sie tatsächlich angefallen ist → 4.000 € netto."], "o": [null, null, "Nach § 249 II 1 darf B Geld statt Herstellung wählen. Er muss A nicht selbst reparieren lassen.", "Ersatzfähig sind die erforderlichen Reparaturkosten nach Gutachten, nicht nur der Wertverlust.", null, "Der Geschädigte ist frei, wie er das Geld verwendet. Eine Verwendungspflicht oder -frist gibt es nicht."]}, "P2-del-17": {"k": "H haftet als Halte", "w": ["Halterin H: § 833 S. 1 – Gefährdungshaftung für ein Luxustier (Familienhund), verschuldensunabhängig, ohne Entlastung. Es kommt nicht darauf an, wer gerade aufpasst.", "Aufpasser N: Er hat den Hund unachtsam frei laufen lassen → § 823 I (Fahrlässigkeit); ggf. auch § 834 (Tieraufseher, mit Entlastungsmöglichkeit).", "Beide haften nebeneinander (Gesamtschuld, § 840 I). Kein Mitverschulden der P."], "o": [null, null, null, null, "Für Luxustiere haftet der Halter verschuldensunabhängig (§ 833 S. 1). Eine Entlastung durch sorgfältige Auswahl gibt es nur bei Nutztieren (§ 833 S. 2).", null]}, "P2-del-18": {"k": "Ersatz der Beerdig", "w": ["Grundsatz: Ersatz bekommt nur der unmittelbar Verletzte. Bei Tötung macht § 844 eine Ausnahme für mittelbar Geschädigte.", "§ 844 I: Die Beerdigungskosten ersetzt S dem, der sie tragen muss (Erben).", "§ 844 II: Unterhaltsberechtigte (Ehefrau und Kinder) bekommen den entgangenen Unterhalt für die mutmaßliche Lebensdauer des Getöteten – nicht dessen ganzes Einkommen."], "o": [null, null, null, null, null, null]}, "P2-del-19": {"k": "K hat einen Anspru", "w": ["Deliktisch: S haftet aus § 831 für M, kann sich aber durch sorgfältige Auswahl und Überwachung entlasten (§ 831 I 2) – das gelingt hier.", "Vertragsähnlich: Mit Betreten des Marktes entsteht ein vorvertragliches Schuldverhältnis (§ 311 II Nr. 2) mit Schutzpflichten (§ 241 II).", "Dort wird das Verschulden des M über § 278 zugerechnet – ohne Entlastungsmöglichkeit. Anspruch aus §§ 280 I, 311 II, 241 II, 278, inklusive Schmerzensgeld (§ 253 II)."], "o": [null, null, null, null, null, null]}, "h16": {"k": "M kann sich entlas", "w": ["G hat fahrlässig den Körper der N verletzt → G haftet selbst aus § 823 I (Verdienstausfall als Folgeschaden, Schmerzensgeld nach § 253 II).", "M gegenüber N: Kein Vertrag zwischen M und N → § 278 scheidet aus. Bleibt § 831: G ist Verrichtungsgehilfe; M hat G aber seit Jahren sorgfältig ausgewählt und kontrolliert → Entlastung (§ 831 I 2) gelingt.", "Ergebnis: N muss sich an G halten."], "o": [null, null, null, null, null, null]}, "a6-6": {"k": "Das Kaufhaus kann ", "w": ["Kaufvertrag? Nein: Ware im Regal ist invitatio ad offerendum; das Kaufhaus hat nichts angenommen. Öffnen ist keine Annahme.", "Aber: Vertragsanbahnung (§ 311 II Nr. 2) → Rücksichtnahmepflichten (§ 241 II). V wusste, dass nur Tester benutzt werden dürfen.", "Anspruch des Kaufhauses aus §§ 280 I, 311 II, 241 II auf Ersatz des Schadens an den geöffneten Produkten."], "o": [null, "Wer etwas öffnet, irrt nicht über den Inhalt einer Erklärung, sondern höchstens über die Rechtsfolgen – ein solcher Rechtsfolgenirrtum berechtigt nicht zur Anfechtung. Außerdem gibt es gar keinen Vertrag.", "Rücktritt setzt einen Vertrag und einen Rücktrittsgrund voraus. Hier fehlt schon der Vertrag.", null, null, null]}, "W-11": {"k": "Die fiktiven Koste", "w": ["Anspruch unstreitig (§ 823 I). Frage nur: Umfang.", "§ 249 II 1: Der Geschädigte kann statt Herstellung Geld verlangen und darf dabei die Werkstatt seines Vertrauens zugrunde legen – er muss sich nicht auf die Werkstatt des Schädigers einlassen.", "Er muss nicht reparieren (fiktive Abrechnung). Umsatzsteuer nur, wenn sie anfällt (§ 249 II 2)."], "o": [null, null, null, null, null, null]}, "W-12": {"k": "Den Wert des Bilde", "w": ["Vertrag (Transport) → Obhutspflicht für das Bild. Fahrlässigkeit des Mitarbeiters wird der GmbH zugerechnet (§ 278) → §§ 280 I, 241 II.", "Umfang: Herstellung unmöglich (Bild zerstört) → Wertersatz in Geld (§ 251 I).", "Ideeller Wert ist immaterieller Schaden; Geld dafür nur in gesetzlich bestimmten Fällen (§ 253 I) – § 253 II nennt Körper, Gesundheit, Freiheit, sexuelle Selbstbestimmung, nicht Sachen."], "o": [null, null, null, null, null, null]}, "W-19": {"k": "N kann Wertersatz ", "w": ["§ 823 I: Eigentum des N am Wintergarten verletzt; grobe Unachtsamkeit → Verschulden. Ein Vertrag ist nicht nötig.", "Umfang: Wiederherstellung unmöglich bzw. nicht genügend → Wertersatz (§ 251 I). Dazu Folgekosten wie der Abtransport des Schutts.", "Kein Anspruch auf einen moderneren Wintergarten (Bereicherungsverbot) und keinen Ersatz für die fremde Eiche. Ein Schreck ist keine Gesundheitsverletzung."], "o": [null, null, null, null, null, null]}, "fb-8-sch2": {"k": "Ja, aus Vertrag un", "w": ["F verletzt die Gesundheit der K fahrlässig (Verätzungen). Anspruchsgrundlagen: Vertrag (§ 280 I, Werk-/Dienstvertrag) und § 823 I.", "Schmerzensgeld: § 253 II gilt seit 2002 für alle Anspruchsgrundlagen, wenn Körper oder Gesundheit verletzt sind – also auch vertraglich.", "Die Einwilligung der K deckte nur eine fachgerechte Behandlung, nicht eine falsche Konzentration."], "o": [null, null, null, null, null, null]}, "fb-3-cic": {"k": "U kann 9.000 € als", "w": ["Kein Vertrag. Grundsatz: Abbruch der Verhandlungen ist erlaubt.", "c.i.c. (§§ 280 I, 311 II Nr. 1, 241 II): S hat zurechenbar das Vertrauen erweckt („Unterschrift nur Formsache“, „bitte mieten Sie schon“) und dann ohne triftigen Grund abgebrochen.", "Rechtsfolge: Vertrauensschaden (negatives Interesse) → 9.000 € Mietkosten. Kein Abschlusszwang, kein entgangener Gewinn. Fahrlässigkeit genügt (Vorsatz nur bei formbedürftigen Verträgen)."], "o": [null, null, null, null, null, null]}, "a6-13": {"k": "R haftet aus § 823", "w": ["§ 823 I: Körperverletzung der M durch zu schnelles Fahren (Fahrlässigkeit); Rechtswidrigkeit indiziert.", "§ 823 II i. V. m. § 229 StGB: Die Strafnorm schützt gerade den Einzelnen → Schutzgesetz. Daneben § 7 StVG.", "Umfang: Heilbehandlung (§ 249) und Schmerzensgeld (§ 253 II) nebeneinander. Am Zebrastreifen hat M Vorrang – kein Mitverschulden."], "o": [null, null, null, null, null, null]}, "a6-21": {"k": "Der Tatbestand des", "w": ["Martin (nicht Käufer) wurde verletzt. Vertrag hat er keinen – aber § 823 I und ProdHaftG setzen keinen Vertrag voraus.", "Produzentenhaftung (§ 823 I): Konstruktionsfehler → Pflichtverletzung des Herstellers, Körperverletzung, Verschulden (Beweislastumkehr) → erfüllt.", "Für den zerstörten Reiniger hilft das ProdHaftG der GmbH nicht (Produkt selbst und gewerblich genutzt); sie hat aber Mängelrechte aus dem Kaufvertrag, inkl. Schadensersatz (§ 437 Nr. 3)."], "o": ["Naturalrestitution hat Vorrang, aber eine explodierte Maschine lässt sich nicht reparieren. Dann wird Geld geschuldet (§ 251 I).", null, "Neben der Nacherfüllung kann die GmbH bei Vertretenmüssen auch Schadensersatz verlangen (§ 437 Nr. 3).", null, null, null]}, "a6-22": {"k": "Die GmbH hat einen", "w": ["Die GmbH zahlt Martin während der Arbeitsunfähigkeit den Lohn weiter.", "Vertraglich: Die Lohnfortzahlung ist für die GmbH ein Mangelfolgeschaden aus dem Kaufvertrag (§§ 437 Nr. 3, 280 I).", "Zusätzlich geht Martins eigener Anspruch auf Verdienstausfall gegen die Herstellerin kraft Gesetzes auf die GmbH über (§ 6 EFZG).", "Das ProdHaftG hilft der GmbH für eigene Vermögensschäden nicht; es ist zudem verschuldensunabhängig und erfasst auch den Endhersteller bei Zulieferteilen."], "o": ["Die Kosten sind ersatzfähig: als Mangelfolgeschaden aus dem Kaufvertrag und über den gesetzlichen Übergang von Martins Anspruch (§ 6 EFZG).", null, null, null, null, null]}, "a6-37": {"k": "Nein, R haftet nic", "w": ["§ 831 und § 278 setzen voraus, dass der Gehilfe in Ausführung der Verrichtung bzw. in Erfüllung einer Pflicht des Geschäftsherrn handelt.", "S kam um 22 Uhr privat vorbei und stahl – sie handelte nur bei Gelegenheit ihrer Tätigkeit, nicht in deren Ausführung.", "Ergebnis: R haftet weder aus § 831 noch über § 278. M muss sich an S halten (§ 823 I, § 823 II i. V. m. § 242 StGB)."], "o": ["Auf sorgfältige Auswahl kommt es erst an, wenn der Gehilfe in Ausführung der Verrichtung gehandelt hat. Ein privater Diebstahl gehört nicht dazu.", null, "S ist als weisungsgebundene Angestellte sowohl Erfüllungs- als auch Verrichtungsgehilfin. Der Grund ist, dass sie nur bei Gelegenheit handelte.", "„Immer“ ist falsch: Der Geschäftsherr haftet nur für Handlungen in Ausführung der Verrichtung, nicht für Straftaten bei Gelegenheit.", null, null]}, "a6-41": {"k": "Ansprüche gegen B ", "w": ["Mäher nur per App steuerbar → Ware mit digitalen Elementen; der Verkäufer B schuldet Updates (§ 475b IV).", "B hat die Updates bereitgestellt und auf die Folgen hingewiesen; H hat sie ignoriert.", "§ 475b V: Beruht der Mangel auf der fehlenden Installation trotz Information, haftet der Unternehmer nicht – weder auf Nacherfüllung noch auf Schadensersatz (keine Kürzung, sondern Ausschluss).", "Gegen den Hersteller kämen allenfalls deliktische Ansprüche in Betracht."], "o": [null, "Ein Update, das bereitgestellt und angekündigt wurde, ist kein Mangel. Den Schaden verursachte H, weil er es nicht installiert hat (§ 475b V).", null, null, null, null]}, "a6-44": {"k": "F kann die Taxikos", "w": ["Wer eine Ausfahrt zuparkt, beeinträchtigt die Nutzung der Garage und des Autos → Eigentumsverletzung (§ 823 I).", "Zusätzlich § 823 II i. V. m. § 240 StGB (Nötigung als Schutzgesetz, unterstellt).", "Schaden: Taxikosten 50 €. Schadensminderungsobliegenheit (§ 254 II) besteht immer, F hat sie aber nicht verletzt – im Feuerwehreinsatz war eine Halter-Suche unzumutbar."], "o": [null, "§ 254 II verlangt nur zumutbare Maßnahmen. Im Feuerwehreinsatz kann F nicht erst nach dem Halter suchen.", "Selbsthilfe (§ 229) ist nur unter engen Voraussetzungen erlaubt, etwa wenn obrigkeitliche Hilfe nicht rechtzeitig zu erlangen ist. „Jederzeit“ ist falsch.", null, null, null]}, "a6-46": {"k": "F hat Ansprüche ge", "w": ["Vertrag F–G (Werkvertrag). G bedient sich des K zur Erfüllung → K ist Erfüllungsgehilfe, egal ob Fachmann oder nicht.", "§ 278: G haftet für das Verschulden des K wie für eigenes, ohne Entlastungsmöglichkeit.", "F hat Mängelrechte bzw. Schadensersatz gegen G. Mit K hat F keinen Vertrag; G kann seinerseits bei K Rückgriff nehmen."], "o": [null, "G darf sich helfen lassen; er haftet dann eben für den Helfer (§ 278). Ob er Rückgriff gegen K nehmen kann, hängt von ihrer Vereinbarung ab.", null, null, null, null]}, "a6-48": {"k": "L hat gegen den He", "w": ["Wer ist verletzt? L (Entleiherin), am Körper. Fehler: Konstruktionsfehler der Gabel.", "§ 1 I ProdHaftG gegen den Hersteller: verschuldensunabhängig, setzt keinen Vertrag voraus. Ersatzfähig ist auch der Folgeschaden (Kosten für die Vertretung in der Konditorei).", "Gegen V scheidet § 280 I aus: Verleiher haften nur für Vorsatz und grobe Fahrlässigkeit (§ 599). Gegen Radlglück sind Mängelrechte nach 5 Jahren verjährt."], "o": ["Ein Anspruch der V gegen L setzt Verschulden der L voraus. Die Gabel brach wegen eines Konstruktionsfehlers, nicht durch L.", "Mängelrechte gegen Radlglück verjähren in zwei Jahren ab Ablieferung (§ 438 I Nr. 3). Nach fünf Jahren sind sie verjährt.", null, "Ein Konstruktionsfehler ist kein allgemeines Lebensrisiko. Für ihn haftet der Hersteller nach dem ProdHaftG.", null, null]}, "a6-69": {"k": "M muss für das Han", "w": ["Vertrag Anton–M (Werkvertrag). M lässt P die Reifen aufziehen → P ist Erfüllungsgehilfe (und als Angestellter zugleich Verrichtungsgehilfe).", "§ 278: M haftet für das Verschulden des P wie für eigenes, ohne Entlastung → §§ 280 I, (634 Nr. 4) i. V. m. § 278.", "P haftet daneben selbst aus § 823 I. M hat zudem eigenes Organisationsverschulden (unerfahrenen Praktikanten allein arbeiten lassen)."], "o": ["Wer fahrlässig das Eigentum eines anderen verletzt, haftet selbst aus § 823 I – auch als Praktikant.", "P ist beides: Erfüllungsgehilfe, weil M ihn zur Erfüllung des Vertrags einsetzt, und Verrichtungsgehilfe, weil er weisungsgebunden ist.", null, "M hat sich des P bedient. Nach § 278 haftet er für dessen Verschulden, als hätte er selbst gehandelt.", null, null]}, "fb-8-831": {"k": "Nein, G kann sich ", "w": ["Zwischen dem Passanten P und G besteht kein Schuldverhältnis → § 278 und §§ 280, 241 II scheiden aus.", "Deliktisch: § 831 I 1 – F ist Verrichtungsgehilfe. Entlastung nach § 831 I 2 bei sorgfältiger Auswahl und Überwachung: zehn Jahre ohne Beanstandung, regelmäßige Kontrolle → gelingt.", "F haftet selbst aus § 823 I. P muss sich an ihn halten."], "o": [null, null, null, null, null, null]}, "fb-8-833": {"k": "F haftet ohne Entl", "w": ["§ 833 S. 1: Gefährdungshaftung des Tierhalters, ohne Verschulden.", "§ 833 S. 2: Ausnahme für Haustiere, die dem Beruf, der Erwerbstätigkeit oder dem Unterhalt des Halters dienen (Nutztiere) – der Halter kann sich durch Beachtung der erforderlichen Sorgfalt entlasten.", "Wachhund auf dem Betriebsgelände = Nutztier → S kann sich entlasten. Familienlabrador = Luxustier → F haftet ohne Entlastung."], "o": [null, null, null, null, null, null]}, "fb-8-del1": {"k": "Nur R hat einen An", "w": ["Das Kabel gehört dem Energieversorger, nicht P oder R.", "R: Durch den Stromausfall verdarben Eier in ihrer Substanz → Eigentumsverletzung → § 823 I.", "P: kann nur nicht backen, nichts ist beschädigt → reiner Vermögensschaden, nicht über § 823 I ersatzfähig. Auch kein betriebsbezogener Eingriff in den Gewerbebetrieb.", "X haftet ggf. aus § 831 mit Entlastungsmöglichkeit."], "o": [null, null, null, null, null, null]}, "fb-8-del2": {"k": "Ja, aus § 823 II i", "w": ["Kein Vertrag; R hat einen reinen Vermögensschaden (Überweisung = Buchgeld, kein Sacheigentum) → § 823 I scheidet aus.", "§ 823 II i. V. m. § 263 StGB: Betrug schützt das Vermögen des Einzelnen → Schutzgesetz.", "§ 826: vorsätzliche sittenwidrige Schädigung (gefälschte Prognosen, Geld für sich verwendet).", "Daneben Bereicherungsrecht – aber nicht „nur“."], "o": [null, null, null, null, null, null]}, "PK-22": {"k": "K hat Ansprüche au", "w": ["Vertragsanbahnung: K war auf dem Weg in den Laden → § 311 II Nr. 2 → Schutzpflichten (§ 241 II). L streute trotz Kenntnis nicht → §§ 280 I, 311 II, 241 II.", "Delikt: Verkehrssicherungspflicht für den Zugang; pflichtwidriges Unterlassen ist eine Verletzungshandlung → § 823 I.", "Beide Ansprüche bestehen nebeneinander (Anspruchskonkurrenz); Schmerzensgeld nach § 253 II bei Fahrlässigkeit."], "o": [null, null, null, null, null, null]}, "PK-23": {"k": "F kann die vollen ", "w": ["A und B haben den Unfall gemeinsam verursacht → beide haften aus § 823 I.", "Mehrere Verantwortliche für denselben Schaden sind Gesamtschuldner (§ 840 I): F kann von jedem die vollen 4.000 € verlangen, insgesamt aber nur einmal (§ 421).", "Wer zahlt, kann vom anderen Ausgleich verlangen (§ 426)."], "o": [null, null, null, null, null, null]}, "P2-del-0": {"k": "Behandlungskosten,", "w": ["§ 823 I: Rechtsgutsverletzungen Körper (Handgelenk) und Eigentum (Brille), fahrlässig, rechtswidrig. Kein Vertrag nötig.", "Umfang: Behandlungskosten und Brille (§ 249), Verdienstausfall als entgangener Gewinn/Folgeschaden (§ 252), Schmerzensgeld (§ 253 II).", "Vorsatz oder eine Bestrafung sind nicht nötig."], "o": [null, null, null, null, null, null]}, "P2-del-1": {"k": "S hat keinen Anspr", "w": ["Das Kabel gehört dem Energieversorger. Die Bäckerei S hat kein eigenes Rechtsgut verloren – die Maschinen sind unbeschädigt, nur für Stunden nicht nutzbar.", "Eine kurze Nutzungsstörung ist keine Eigentumsverletzung; ein Eingriff in den Gewerbebetrieb setzt einen betriebsbezogenen Eingriff voraus (fehlt bei Kabelbruch).", "Ergebnis: reiner Vermögensschaden → über § 823 I nicht ersatzfähig; § 826 scheitert am fehlenden Vorsatz."], "o": [null, null, "S ist nicht Partei des Bauvertrags und steht ihm nicht so nahe, dass sie in seinen Schutzbereich einbezogen wäre.", "§ 831 knüpft an eine widerrechtliche Schädigung durch den Gehilfen an. Bei S liegt gar keine Rechtsgutsverletzung vor.", null, null]}, "P2-del-2": {"k": "§ 823 II i. V. m. ", "w": ["Der Kunde hat sein Geld freiwillig übereignet → keine Eigentumsverletzung, sondern ein Vermögensschaden.", "§ 823 II i. V. m. § 263 StGB: Der Betrug schützt das Vermögen des Einzelnen → Schutzgesetz. H handelte wissentlich (Vorsatz).", "Daneben § 826. Vertragliche und deliktische Ansprüche bestehen nebeneinander."], "o": [null, null, null, "§ 831 regelt die Haftung für Gehilfen. H hat selbst gehandelt, also haftet er unmittelbar.", "§ 833 betrifft die Haftung des Tierhalters und hat mit Produkten nichts zu tun.", null]}, "P2-del-3": {"k": "Tim haftet selbst,", "w": ["Deliktsfähigkeit (§ 828): unter 7 Jahren nie (I); im Straßenverkehr bis 10 Jahre nur bei Vorsatz (II); sonst von 7 bis 18 Jahren, wenn die zur Erkenntnis der Verantwortlichkeit erforderliche Einsicht vorhanden ist (III).", "Tim ist 9, handelte im Garten (kein Straßenverkehr) und wusste, dass es verboten ist und schadet → Einsicht vorhanden.", "Er haftet selbst aus § 823 I. Die Eltern haften daneben nur bei Aufsichtspflichtverletzung (§ 832)."], "o": [null, null, null, null, "Für die Haftung aus Delikt kommt es nicht auf die Zustimmung der Eltern an, sondern nur auf die Einsichtsfähigkeit des Kindes (§ 828 III).", "§ 829 (Billigkeitshaftung) greift nur, wenn das Kind nach §§ 827, 828 nicht verantwortlich ist. Tim ist aber verantwortlich."]}, "P2-del-4": {"k": "V haftet aus § 832", "w": ["Mia ist unter 7 → deliktsunfähig (§ 828 I) → haftet nicht selbst.", "Vater V: § 832 – wer kraft Gesetzes zur Aufsicht über einen Minderjährigen verpflichtet ist, haftet für den Schaden, den dieser einem Dritten widerrechtlich zufügt. Die Aufsichtspflichtverletzung wird vermutet.", "Eine 6-Jährige unbeaufsichtigt an der Hauptstraße, während er aufs Handy schaut → Entlastung unmöglich."], "o": [null, null, null, "§ 278 setzt ein Schuldverhältnis zwischen V und dem Autobesitzer voraus. Das gibt es nicht.", "Verrichtungsgehilfe ist, wer weisungsgebunden eine Tätigkeit für einen anderen ausübt. Ein spielendes Kind erledigt keine Verrichtung für den Vater.", "§ 832 knüpft an die Verletzung der Aufsichtspflicht an; Fahrlässigkeit genügt und wird vermutet."]}, "P2-del-5": {"k": "P kann von A aus §", "w": ["P ist zufälliger Passant → kein Schuldverhältnis mit U → § 278 scheidet aus.", "A haftet selbst aus § 823 I (Eigentum, Fahrlässigkeit genügt).", "U: § 831 I 1 (A ist Verrichtungsgehilfe). Entlastung nach § 831 I 2 durch sorgfältige Auswahl und Überwachung – „seit Jahren zuverlässig und regelmäßig kontrolliert“ → gelingt."], "o": [null, null, null, null, "Eine Teilung gibt es nur unter Gesamtschuldnern im Innenverhältnis. Hier haftet U wegen der Entlastung gar nicht; A haftet voll.", null]}, "P2-del-6": {"k": "H haftet aus § 823", "w": ["Verletzungshandlung durch Unterlassen: genügt, wenn eine Pflicht zum Handeln bestand – hier die Verkehrssicherungspflicht (Streupflicht), durch Satzung auf H übertragen.", "H streut trotz Glatteis nicht → Pflichtverletzung, fahrlässig. B wird am Körper verletzt.", "§ 823 I (auch § 823 II i. V. m. Satzung denkbar). Kein Vertrag nötig; der Zweck des Weges ist gleichgültig."], "o": [null, null, null, null, "Die Gemeinde hat die Streupflicht durch Satzung auf die Anlieger übertragen. Verantwortlich ist deshalb H.", null]}, "P2-del-7": {"k": "H haftet aus § 833", "w": ["§ 833 S. 1: Der Halter haftet für Schäden durch sein Tier verschuldensunabhängig (Gefährdungshaftung).", "Entlastung nach § 833 S. 2 nur bei Nutztieren (Beruf, Erwerb, Unterhalt). Ein reines Familienhaustier ist ein Luxustier → keine Entlastung, auch bei ordnungsgemäßer Leine.", "Joggen ist kein Mitverschulden. Ein etwaiger Leinenhersteller haftet allenfalls daneben."], "o": [null, null, null, "H haftet aus § 833 S. 1 in jedem Fall. Der Leinenhersteller könnte nur zusätzlich (ProdHaftG) haften.", "§ 833 knüpft an die typische Tiergefahr an. Frühere Vorfälle sind keine Voraussetzung.", null]}, "P2-del-8": {"k": "S kann sich als Ha", "w": ["Grundsatz § 833 S. 1: verschuldensunabhängige Tierhalterhaftung.", "Ausnahme § 833 S. 2: Bei Haustieren, die dem Erwerb des Halters dienen (Herde als Erwerbsquelle), kann sich der Halter entlasten, wenn er die erforderliche Sorgfalt beachtet hat. Die Beweislast trägt S.", "Sorgfältig gewarteter Zaun → Entlastung gelingt."], "o": [null, null, null, null, "Für Schäden durch Tiere ist § 833 die speziellere Norm. § 823 I wäre nur bei eigenem Verschulden des S einschlägig.", null]}, "P2-del-9": {"k": "S muss nicht zahle", "w": ["S verletzt den Hund (Tiere wie Sachen, § 90a) → § 823 I wäre erfüllt, wenn S rechtswidrig handelte.", "Notwehr (§ 227) braucht einen Angriff eines Menschen – ein frei laufender Hund ist das nicht.", "Defensivnotstand (§ 228): Gefahr droht von der Sache selbst; Abwehr war erforderlich und der Schaden nicht außer Verhältnis → gerechtfertigt → kein Ersatz."], "o": [null, null, "Wer gerechtfertigt handelt, schuldet keinen Ersatz. Eine Teilung nach „beiderseitigem Schaden“ gibt es nicht.", null, null, null]}, "fb-3-neb": {"k": "Ja, aus §§ 280 I, ", "w": ["Der Schrank ist mangelfrei → keine Mängelrechte. Beschädigt wurde ein anderes Rechtsgut (Parkett).", "Aus dem Vertrag folgen Rücksichtnahmepflichten (§ 241 II). Der Monteur verletzt sie; § 278 rechnet sein Verschulden M ohne Entlastung zu.", "Anspruch aus §§ 280 I, 241 II, 278 – Schadensersatz neben der Leistung, ohne Frist. Der Monteur haftet daneben aus § 823 I."], "o": [null, null, null, null, null, null]}, "L4-4": {"k": "Nein, das reine Ve", "w": ["Kein Beratungsvertrag (Gefälligkeit beim Abendessen) → nur Delikt.", "§ 823 I: Welches Rechtsgut? Eigentum nicht (K hat das Geld freiwillig investiert), Gesundheit nicht (Schlafstörungen ohne Krankheitswert). Es bleibt ein Vermögensschaden.", "Das Vermögen ist kein Rechtsgut des § 823 I. § 823 II (Betrug) und § 826 scheitern am fehlenden Vorsatz."], "o": [null, null, null, null, null, null]}, "L4-5": {"k": "Nein, U kann sich ", "w": ["Kein Schuldverhältnis U–P → kein § 278.", "§ 831 I 1: F ist weisungsgebundener Angestellter (Verrichtungsgehilfe) und hat P in Ausführung seiner Tätigkeit verletzt.", "Entlastung § 831 I 2: Führerschein, Fahreignungsregister, Probefahrt, regelmäßige Kontrolle → sorgfältige Auswahl und Überwachung → gelingt.", "F haftet selbst (§ 823 I); U ggf. als Halter verschuldensunabhängig (§ 7 StVG)."], "o": [null, null, null, null, null, null]}, "L4-6": {"k": "Ja, möglich, weil ", "w": ["Kai ist 8 → nicht unter § 828 I. § 828 II: Kinder zwischen 7 und 10 haften bei Unfällen mit Kfz nur bei Vorsatz – aber nach dem BGH nicht bei Zusammenstößen mit parkenden Autos (keine typische Überforderung durch den fließenden Verkehr).", "Also § 828 III: Haftung, wenn Kai die zur Erkenntnis der Verantwortlichkeit nötige Einsicht hatte – er wusste, dass er aufpassen muss.", "Die Eltern können daneben aus § 832 haften."], "o": [null, null, null, null, null, null]}, "L4-7": {"k": "850 €: Behandlungs", "w": ["ProdHaftG (§ 1 I): verschuldensunabhängig für Personen- und Sachschäden durch ein fehlerhaftes Produkt.", "Personenschaden: Behandlungskosten 150 € – voll ersatzfähig.", "Sachschaden: nur an anderen, privat genutzten Sachen (Küche 1.200 €), abzüglich 500 € Selbstbeteiligung (§ 11) → 700 €. Der Wasserkocher selbst ist nicht ersatzfähig (§ 1 I 2).", "Summe: 150 € + 700 € = 850 €."], "o": [null, null, null, null, null, null]}, "L4-8": {"k": "Nach dem BGH begrü", "w": ["A haftet für die Vorfahrtsverletzung (§ 823 I, § 7 StVG).", "Mitverschulden (§ 254 I) kann auch im Unterlassen von Selbstschutzmaßnahmen liegen, die ein verständiger Mensch ergreift.", "Der BGH (2014, Unfall vor 2011) hat entschieden: Bei Alltagsradfahrern ohne Helm kein Mitverschulden, weil Helmtragen damals nicht allgemein üblich war. Für spätere Unfälle ist das offen."], "o": [null, null, null, null, null, null]}, "fb-7-se": {"k": "1, 3 und 5", "w": ["Schaden durch den überhitzten Wasserkocher an anderen Sachen = Mangelfolgeschaden → Schadensersatz neben der Leistung (§§ 437 Nr. 3, 280 I), keine Frist (Aussage 1).", "Vertretenmüssen des Händlers H: Er verkaufte ein originalverpacktes Markenprodukt mit unerkennbarem Fehler; den Hersteller muss er sich nicht zurechnen lassen → er kann sich entlasten (Aussage 3).", "Der Hersteller haftet daneben aus § 823 I bzw. ProdHaftG (Aussage 5) – nach ProdHaftG mit 500 € Selbstbeteiligung."], "o": [null, null, null, null, null, null]}, "fb-3-pv": {"k": "300 € aus §§ 280 I", "w": ["Zwei Schäden trennen.", "Mietwagen: entsteht durch die Verspätung → Verzögerungsschaden (§§ 280 I, II, 286). Verzug ohne Mahnung, weil der Termin („Freitag“) kalendermäßig bestimmt war (§ 286 II Nr. 1); Vergessen ist fahrlässig.", "Beschädigung durch den Mechaniker: Verletzung einer Rücksichtnahmepflicht (§ 241 II), Zurechnung über § 278 → §§ 280 I, 241 II.", "Beides Schadensersatz neben der Leistung → keine Frist."], "o": [null, null, null, null, null, null]}, "W-1": {"k": "Kaufvertrag über 4", "w": ["Angebot und Annahme? Viktors Post ist mindestens invitatio; spätestens Klaras Erklärung und Viktors Einverständnis schließen den Vertrag.", "Inhalt: Auslegung nach dem objektiven Empfängerhorizont (§§ 133, 157). Klara durfte 450 € verstehen → Vertrag zu 450 €.", "Viktor wollte 540 € schreiben, hat sich aber vertippt → Erklärungsirrtum (§ 119 I Alt. 2): Er wollte eine Erklärung dieses Inhalts gar nicht abgeben.", "Folge: Anfechtung möglich (unverzüglich, § 121), dann Vertrauensschaden (§ 122). Die Kratzer betreffen Mängelrechte, nicht den Vertragsschluss."], "o": [null, null, null, null, null, null]}, "W-2": {"k": "Kein Vertrag; Ingo", "w": ["Unbestellte Lieferung eines Unternehmers an einen Verbraucher → § 241a I.", "Folge: Durch die Lieferung entsteht kein Anspruch gegen den Verbraucher – kein Vertrag, kein Zahlungs-, Herausgabe- oder Nutzungsersatzanspruch.", "Die Klausel „Wenn Sie behalten, gilt …“ ändert nichts: Schweigen ist keine Annahme, und § 241a verdrängt § 151.", "Ingolf muss weder zahlen noch zurückschicken."], "o": [null, null, null, null, null, null]}, "W-3": {"k": "Sie können am 1.12", "w": ["Online-Kauf Verbraucher–Unternehmer → Fernabsatzvertrag → Widerrufsrecht (§§ 312c, 312g I, 355).", "Frist: 14 Tage ab Erhalt der Ware (§ 356 II Nr. 1a) – aber nicht, bevor ordnungsgemäß belehrt wurde (§ 356 III 1). Die Belehrung war nicht abrufbar.", "Ohne Belehrung erlischt das Widerrufsrecht spätestens 12 Monate und 14 Tage nach Erhalt (§ 356 III 2).", "Am 1.12. ist ein Widerruf also möglich – formfrei, aber eindeutig."], "o": [null, null, null, null, null, null]}, "W-4": {"k": "Ja, Auslobung als ", "w": ["Der Zettel ist kein Vertragsangebot, sondern eine Auslobung (§ 657): öffentliches Versprechen einer Belohnung für eine Handlung.", "Die Auslobung ist eine einseitige, nicht empfangsbedürftige Willenserklärung → wirksam mit öffentlicher Bekanntmachung.", "§ 657 a. E.: Der Lohn steht auch dem zu, der die Handlung ohne Rücksicht auf die Auslobung vorgenommen hat.", "Theresa hat Bruno gefunden → 200 €."], "o": [null, null, null, null, null, null]}, "W-5": {"k": "Ja, Uwes Annahme g", "w": ["Bettinas Anfrage enthält alle wesentlichen Punkte (Uhr, Reparatur, 200 €) → Angebot. Uwes Mail um 23 Uhr = Annahme.", "Zugang (§ 130 I 1): wenn die Erklärung in den Machtbereich gelangt und mit Kenntnisnahme zu rechnen ist – spätestens aber mit tatsächlicher Kenntnisnahme. Bettina las um 23.30 Uhr → zugegangen → Vertrag zu 200 €.", "Uwes Mail um 3.30 Uhr: Widerruf wirkt nur, wenn er vorher oder gleichzeitig zugeht (§ 130 I 2) → zu spät, wirkungslos."], "o": [null, null, null, null, null, null]}, "h2": {"k": "Ja, durch die Ausl", "w": ["Vs Angebot mit Annahmefrist bis Freitag (§ 148). Die Annahme muss innerhalb der Frist zugehen, nicht nur abgeschickt werden.", "Zugang der E-Mail (§ 130 I): Machtbereich + Kenntnisnahme unter gewöhnlichen Umständen. Bei Geschäftspost Freitag 23:40 Uhr ist damit erst Montag 8 Uhr zu rechnen → verspätet.", "Verspätete Annahme = neues Angebot (§ 150 I).", "V nimmt dieses Angebot konkludent durch Auslieferung am Dienstag an → Vertrag zustande."], "o": [null, null, null, null, null, null]}, "h3": {"k": "Der Vertrag gilt m", "w": ["Vertrag ist schon am Telefon geschlossen (§ 147 I). Streit nur über den Inhalt.", "Kaufmännisches Bestätigungsschreiben (§ 346 HGB): Unter Kaufleuten gilt der Inhalt des Schreibens, wenn der Empfänger nicht unverzüglich widerspricht – Grenze nur bei bewusster Falschbestätigung oder so starker Abweichung, dass der Absender nicht mit Billigung rechnen konnte.", "Hier weicht es zugunsten des Empfängers H ab → mit Billigung war zu rechnen.", "Erst recht muss der Absender S sein eigenes Schreiben gegen sich gelten lassen → „frei Baustelle“ gilt, keine Frachtkosten."], "o": [null, null, null, null, "S hat genau das geschrieben, was er schreiben wollte. Ein Irrtum über die Wirkung seines Schweigens oder Schreibens berechtigt nicht zur Anfechtung.", null]}, "P2-vs-10": {"k": "Der Vertrag kommt ", "w": ["S hat das Angebot vor seinem Tod abgegeben (abgeschickt).", "§ 130 II: Tod nach Abgabe macht die Erklärung nicht unwirksam; sie wird mit Zugang bei H wirksam.", "§ 153: Der Vertrag kommt trotz Tod des Antragenden zustande, wenn kein anderer Wille anzunehmen ist – bei einem Münzkauf nicht ersichtlich.", "Vertragspartnerin ist die Erbin E (§ 1922)."], "o": [null, "S hat die Erklärung noch zu Lebzeiten abgegeben. Nach § 130 II bleibt sie wirksam und geht später noch zu.", null, null, "Für einen Kauf braucht es keine Genehmigung des Nachlassgerichts. E tritt als Erbin automatisch in die Rechtslage ein.", null]}, "P2-vs-11": {"k": "Die Kündigung ging", "w": ["Zugang verlangt Machtbereich + zu erwartende Kenntnisnahme (§ 130 I).", "Die Ehefrau ist nach der Verkehrsanschauung Empfangsbotin des M: Sie ist geeignet und typischerweise bereit, Post weiterzugeben.", "Bei Empfangsboten geht die Erklärung zu, wenn unter normalen Umständen mit der Weitergabe zu rechnen ist – hier, als M abends heimkommt.", "Dass F den Brief vergisst, ist Risiko des Empfängers M."], "o": [null, "Die Übergabe an F bringt den Brief noch nicht in die Hände des M. Zugang tritt erst ein, wenn F ihn bei normalem Ablauf weitergegeben hätte.", null, null, "Erklärungsbote ist, wer für den Absender handelt. F wohnt mit M zusammen und nimmt für ihn entgegen – sie ist seine Empfangsbotin.", null]}, "P2-vs-12": {"k": "K haftet nicht, we", "w": ["Vertragliche Haftung braucht eine Pflicht aus einem Schuldverhältnis.", "Rechtsbindungswille? Nach dem BGH (Lottogemeinschaft) wollte niemand, dass der Ausfüllende für entgangene Millionengewinne haftet → für die Abgabe des Scheins bloße Gefälligkeit.", "Delikt scheidet aus: Der entgangene Gewinn ist ein reiner Vermögensschaden, kein Rechtsgut des § 823 I."], "o": ["Die Mitspieler bilden zwar eine Gemeinschaft für die Gewinnverteilung, eine einklagbare Pflicht zur Abgabe des Scheins wollte aber niemand begründen.", null, null, "Ein Haftungsmaßstab wie grobe Fahrlässigkeit spielt erst eine Rolle, wenn überhaupt eine Pflicht besteht. Hier fehlt schon die vertragliche Pflicht.", null, "§ 762 betrifft Schulden aus dem Spiel selbst. Hier geht es um Schadensersatz für einen vergessenen Schein."]}, "P2-vs-13": {"k": "Ein Vertrag über 1", "w": ["Auslegung (§§ 133, 157): Vorrang hat das übereinstimmend Gewollte beider Parteien vor dem objektiven Erklärungswert.", "Beide meinten den 12er-Karton → falsa demonstratio non nocet: Die falsche (mehrdeutige) Bezeichnung schadet nicht.", "Vertrag über 12 Flaschen; kein Dissens, kein Irrtum, keine Form nötig."], "o": ["Der objektive Empfängerhorizont schützt den Empfänger. Wenn beide dasselbe meinen, braucht keiner Schutz – dann gilt das Gewollte.", null, null, null, "Die Menge lässt sich durch Auslegung bestimmen: Beide meinten 12 Flaschen.", null]}, "P2-vs-14": {"k": "Kein Vertrag, weil", "w": ["Auslegung: „Dollar“ ist objektiv mehrdeutig, und die Umstände ergeben keine Klärung.", "Beide glauben, sich geeinigt zu haben → versteckter Dissens (§ 155).", "§ 155: Vertrag gilt nur, wenn er auch ohne diesen Punkt geschlossen worden wäre. Der Preis ist wesentlich (essentiale negotii) → kein Vertrag."], "o": [null, null, null, "Anfechtung setzt einen geschlossenen Vertrag voraus. Hier haben sich die Parteien über den Preis gar nicht geeinigt.", null, null]}, "P2-vs-15": {"k": "Im Zweifel ist kei", "w": ["Beide wissen, dass ein Punkt (Liefertermin) noch offen ist und einvernehmlich geregelt werden soll → offener Dissens.", "§ 154 I 1: Solange sich die Parteien nicht über alle Punkte geeinigt haben, über die eine Vereinbarung getroffen werden sollte, ist der Vertrag im Zweifel nicht geschlossen.", "Auch eine Einigung über Ware und Preis genügt nicht; das Gesetz (§ 271) füllt die Lücke nicht, weil die Parteien selbst regeln wollten."], "o": [null, null, null, "§ 155 betrifft den Fall, dass die Parteien glauben, sich geeinigt zu haben. Hier wissen beide, dass der Liefertermin offen ist.", null, null]}, "P2-vs-16": {"k": "Durch Angebot des ", "w": ["Wer einen Automaten aufstellt, will mit jedem kontrahieren, der Geld einwirft → Angebot ad incertas personas.", "Das Angebot steht unter der Bedingung, dass Vorrat vorhanden ist und der Automat funktioniert.", "R nimmt durch den Geldeinwurf (und die Wahl) konkludent an → Kaufvertrag mit dem Betreiber B. Die Ausgabe der Flasche ist die Übereignung."], "o": ["Das Nachfüllen geschieht unabhängig von R. Das Angebot liegt schon im Aufstellen des Automaten.", null, null, "Ein Automat gibt keine eigene Willenserklärung ab. Er transportiert nur das bereits im Aufstellen liegende Angebot des B.", null, null]}, "P2-vs-17": {"k": "Ein Vertrag über 1", "w": ["Bei Internetauktionen ist das Einstellen ein Angebot an den Höchstbietenden (nicht nur invitatio).", "Wer abbricht, ohne gesetzlichen Grund, hat einen Vertrag mit dem zu diesem Zeitpunkt Höchstbietenden geschlossen – hier K zu 1 €.", "Missverhältnis zwischen 1 € und 5.000 € ist kein Wucher und nach dem BGH auch kein Rechtsmissbrauch – das Risiko hat V mit dem Startpreis übernommen.", "V kann nicht liefern (Abbruch, Auto behalten oder anders verkauft) → Schadensersatz statt der Leistung, i. d. R. Wertdifferenz."], "o": [null, null, "Wucher (§ 138 II) verlangt die Ausbeutung einer Zwangslage oder Unerfahrenheit. V hat den Startpreis selbst gewählt.", null, null, null]}, "P2-vs-18": {"k": "Es liegt eine anfe", "w": ["Handheben gilt dort als Gebot → äußerer Tatbestand einer Willenserklärung liegt vor.", "G fehlt das Erklärungsbewusstsein. Nach dem BGH liegt trotzdem eine Willenserklärung vor, wenn er bei verkehrsüblicher Sorgfalt hätte erkennen können, dass sein Verhalten als Erklärung verstanden wird (zurechenbar).", "G kann aber analog § 119 I anfechten – dann schuldet er Vertrauensschaden (§ 122)."], "o": ["Nach dem BGH ist fehlendes Erklärungsbewusstsein unschädlich, wenn G hätte erkennen können, dass Handheben als Gebot gilt.", null, null, "Bei der Versteigerung kommt der Vertrag durch den Zuschlag zustande (§ 156), nicht durch das Abholen.", null, null]}, "P2-vs-19": {"k": "Der Vertrag kam be", "w": ["Die Bestellung des K ist das Angebot.", "§ 151: Die Annahme muss nicht zugehen, wenn das nach der Verkehrssitte nicht zu erwarten ist (Versandhandel: sofortige Lieferung).", "Die Annahme liegt in der Willensbetätigung – dem Absenden der Maschine → Vertrag mit Versand geschlossen.", "Die spätere Stornierung kommt zu spät, kann aber ggf. als Widerruf nach § 355 wirken."], "o": [null, null, "Die Annahme liegt schon im Versand. Wann die Ware ankommt, ist für den Vertragsschluss gleichgültig.", null, null, null]}, "P2-vs-20": {"k": "Kein Vertrag; er k", "w": ["Warenauslage im Regal = invitatio ad offerendum (h. M.): Der Händler will sich nicht vorab an jeden binden.", "Das Angebot macht die Kundin, wenn sie die Ware an der Kasse vorlegt; die Annahme liegt im Registrieren.", "Beim Einlegen in den Wagen gibt es also noch keinen Vertrag; K kann die Flasche zurückstellen."], "o": [null, null, null, null, "Vor der Kasse gab es noch keinen Vertrag, den man hätte aufheben können.", null]}, "P2-vs-0": {"k": "Kein Vertrag: Erst", "w": ["Schaufensterauslage = invitatio ad offerendum: Der Händler will entscheiden, ob und mit wem er abschließt (Vorrat, Zahlungsfähigkeit).", "Das Angebot macht K mit „Ich nehme den Mantel für 49 €“.", "Die Verkäuferin lehnt ab → kein Vertrag. Eine Anfechtung ist mangels Vertrag gar nicht nötig."], "o": [null, "Eine Anfechtung setzt einen geschlossenen Vertrag voraus. Hier hat B Ks Angebot abgelehnt.", null, null, null, "Die Auslage ist kein Angebot, also konnte K nichts annehmen. Ihre Erklärung ist selbst das Angebot."]}, "P2-vs-1": {"k": "Kein Vertrag: Die ", "w": ["Shop-Darstellung = invitatio ad offerendum. Das Angebot macht K mit der Bestellung.", "Die automatische E-Mail bestätigt nur den Eingang (§ 312i I 1 Nr. 3) und kündigt eine Prüfung an → nach ihrem Wortlaut keine Annahme.", "H storniert, bevor er annimmt → kein Vertrag. Auf eine Anfechtung kommt es nicht an."], "o": [null, null, null, "Verbraucherschutz gibt K Informations- und Widerrufsrechte, ersetzt aber keine Annahmeerklärung des H.", null, null]}, "P2-vs-2": {"k": "Kein Vertrag: Das ", "w": ["Telefonat = Gespräch unter Anwesenden (§ 147 I 2).", "Ein Angebot unter Anwesenden kann nur sofort angenommen werden (§ 147 I 1). Mit Ende des Telefonats erlischt es (§ 146).", "Bs „ich überlege“ ist keine Annahme; As Schweigen gewährt keine Frist. Bs Anruf am nächsten Tag ist ein neues Angebot, das A nicht annimmt."], "o": [null, "Eine Annahmefrist muss der Anbietende bestimmen (§ 148). As Schweigen auf die Bitte um Bedenkzeit setzt keine Frist.", null, null, "Ein Angebot, das unter Anwesenden nicht sofort angenommen wird, erlischt von selbst (§ 146). Ein Widerruf ist nicht nötig.", null]}, "P2-vs-3": {"k": "Ein Vertrag ist zu", "w": ["Annahmefrist bis 15.3. (§ 148); Zugang erst 17.3. → grundsätzlich verspätet.", "§ 149: Wurde die Annahme so abgeschickt, dass sie bei normaler Beförderung rechtzeitig angekommen wäre, und muss V das erkennen (Poststempel), muss er die Verspätung unverzüglich anzeigen.", "Unterlässt er das, gilt die Annahme als nicht verspätet (§ 149 S. 2) → Vertrag geschlossen."], "o": [null, "§ 150 I gilt nur für echte verspätete Annahmen. § 149 S. 2 fingiert hier die Rechtzeitigkeit, wenn V schweigt.", null, null, null, null]}, "P2-vs-4": {"k": "Kein Vertrag: Bs A", "w": ["Annahme unter Erweiterungen, Einschränkungen oder Änderungen gilt als Ablehnung verbunden mit einem neuen Angebot (§ 150 II).", "„Einverstanden, aber zu 480 €“ ändert den Preis → neues Angebot des B.", "G hat geschwiegen; Schweigen ist grundsätzlich keine Annahme → kein Vertrag."], "o": ["§ 150 II sagt ausdrücklich: Wer unter Änderungen „annimmt“, lehnt ab und macht ein neues Angebot.", null, null, null, null, null]}, "P2-vs-5": {"k": "Es gilt der Inhalt", "w": ["Vertrag mündlich geschlossen; das Schreiben ergänzt ein Zahlungsziel.", "Kaufmännisches Bestätigungsschreiben (§ 346 HGB): Unter Kaufleuten gilt der bestätigte Inhalt, wenn der Empfänger nicht unverzüglich widerspricht.", "Grenze: bewusste Falschbestätigung oder so erhebliche Abweichung, dass mit Billigung nicht zu rechnen war. Ein übliches Zahlungsziel von 30 Tagen ist keine solche Abweichung → es gilt."], "o": [null, null, "Der Vertrag bestand schon seit dem Telefonat. Das Schreiben legt nur seinen Inhalt fest.", null, null, null]}, "P2-vs-6": {"k": "Kein Vertrag; U ha", "w": ["Unbestellte Lieferung eines Unternehmers an eine Verbraucherin → § 241a I.", "Kein Vertrag: Schweigen ist keine Annahme, und die Klausel „gilt als vereinbart“ kann daran nichts ändern.", "§ 241a I schließt alle Ansprüche gegen S aus – Zahlung, Rücksendung, Wertersatz."], "o": [null, null, null, null, null, null]}, "P2-vs-7": {"k": "Am 1. 4., weil mit", "w": ["Zugang unter Abwesenden (§ 130 I 1): Machtbereich + Kenntnisnahme unter gewöhnlichen Umständen zu erwarten.", "Mit dem Einwurf gelangt der Brief in Ms Machtbereich. Nachts um 23:30 Uhr leert aber niemand den Briefkasten.", "Kenntnisnahme ist erst am nächsten Tag zur üblichen Leerungszeit zu erwarten → Zugang am 1.4. Auf die tatsächliche Leerung kommt es nicht an."], "o": [null, null, null, null, null, null]}, "P2-vs-8": {"k": "Am Montag um 8 Uhr", "w": ["Bei Unternehmern ist mit Kenntnisnahme nur während der Geschäftszeiten zu rechnen.", "Eine E-Mail am Sonntag gelangt zwar in den Machtbereich, gelesen wird aber erst bei Geschäftsbeginn am Montag um 8 Uhr.", "Zugang am Montag 8 Uhr – unabhängig davon, wann die Mitarbeiterin die Mail tatsächlich liest."], "o": [null, null, null, null, null, "§ 193 verschiebt nur das Ende einer Frist, wenn es auf einen Sonntag fällt. Mit dem Zugang hat das nichts zu tun."]}, "P2-vs-9": {"k": "Kein Vertrag, weil", "w": ["Widerruf eines Angebots: wirksam, wenn er vorher oder gleichzeitig mit dem Angebot zugeht (§ 130 I 2).", "E-Mail um 9 Uhr, Brief um 10 Uhr – beide im Machtbereich des B; mit Kenntnisnahme ist für beide zu rechnen. Der Widerruf geht nicht später zu als das Angebot.", "Also wurde das Angebot nie wirksam. Wann B was liest, ist gleichgültig → kein Vertrag."], "o": [null, null, null, "Es kommt nicht darauf an, wann der Widerruf erklärt wurde, sondern ob er spätestens gleichzeitig mit dem Angebot zugeht.", null, null]}, "a6-19": {"k": "Am 10. März, als d", "w": ["Zugang einer E-Mail beim Unternehmen: sobald sie im Postfach abrufbar ist und während der Geschäftszeiten mit Kenntnisnahme zu rechnen ist.", "Montag 14 Uhr liegt in der Geschäftszeit → Zugang noch am 10. März.", "Die Krankheit des Mitarbeiters fällt in die Risikosphäre des Empfängers. Ein Autohaus mit fünf Mitarbeitern muss den Posteingang organisieren."], "o": [null, null, null, null, null, null]}, "fb-2-rg1": {"k": "S hat Anspruch auf", "w": ["Anspruchsgrundlage ist kein Vertrag, sondern die Auslobung (§ 657): einseitiges Versprechen einer Belohnung durch öffentliche Bekanntmachung.", "Eine Annahme ist nicht nötig. Deshalb kommt es weder auf Kenntnis noch auf Geschäftsfähigkeit der S an.", "§ 657 Hs. 2: Der Lohn steht auch dem zu, der nicht mit Rücksicht auf die Auslobung gehandelt hat → S bekommt 200 €."], "o": [null, null, null, null, null, null]}, "PK-33": {"k": "Ein Kaufvertrag is", "w": ["Online-Auktion: Das Einstellen ist ein verbindliches Angebot an den Höchstbietenden; die Annahme liegt im Gebot. § 156 (Zuschlag) passt nicht, weil es keinen Zuschlag gibt.", "Bricht V ohne berechtigten Grund (z. B. Verlust, Diebstahl) ab, kommt der Vertrag mit dem zu diesem Zeitpunkt Höchstbietenden zustande.", "Preis = Höchstgebot 1.250 €. Das Missverhältnis zum Wert macht den Vertrag nicht sittenwidrig (BGH) – V hat das Risiko selbst gewählt."], "o": [null, null, null, null, null, null]}, "PK-6": {"k": "Kein Vertrag: Die ", "w": ["Annahmefrist bis Freitag (§ 148): Die Annahme muss bis dahin zugehen.", "Zugang der E-Mail (§ 130 I): Am Freitag um 23:50 Uhr ist bei einem Unternehmen nicht mehr mit Kenntnisnahme zu rechnen → Zugang erst Montag früh → verspätet.", "Verspätete Annahme = neues Angebot (§ 150 I); U nimmt nicht an → kein Vertrag.", "§ 149 hilft nicht: Er setzt eine rechtzeitig abgeschickte Erklärung mit Transportverzögerung voraus."], "o": [null, null, null, null, null, null]}, "PK-7": {"k": "Der Gerichtsstand ", "w": ["Vertrag am Telefon geschlossen; das Schreiben ergänzt Zahlungsziel und Gerichtsstand.", "Kaufmännisches Bestätigungsschreiben (§ 346 HGB): Beide sind Kaufleute, das Schreiben geht zeitnah zu und gibt das Ergebnis der Verhandlung wieder. Schweigt der Empfänger, gilt der Inhalt.", "Eine Gerichtsstandsklausel ist unter Kaufleuten zulässig (§ 38 I ZPO) und keine so grobe Abweichung, dass V nicht mit Billigung rechnen durfte → gilt.", "Ein Irrtum über die Bedeutung des Schweigens berechtigt nicht zur Anfechtung."], "o": [null, null, null, null, null, null]}, "rh6-5": {"k": "Der Zugang der Ann", "w": ["Minibar mit Preisliste im Zimmer: V will an den Gast verkaufen, sobald dieser zugreift; Vorrat und Bonität sind gesichert → Angebot (nicht nur invitatio).", "K nimmt an, indem sie die Flasche öffnet und trinkt – Betätigung des Annahmewillens.", "Zugang der Annahme ist nach der Verkehrssitte entbehrlich (§ 151 S. 1): Niemand erwartet, dass der Gast nachts die Rezeption anruft.", "Vertrag über die ganze Flasche → 4,50 €."], "o": [null, null, null, null, null, null]}, "V-0": {"k": "Eine WE liegt vor,", "w": ["Äußerer Tatbestand: Handheben gilt in der Versteigerung als Gebot (§ 156).", "Innerer Tatbestand: Handlungswille ja (B winkt bewusst), Erklärungsbewusstsein nein (er will nur grüßen).", "BGH: Fehlendes Erklärungsbewusstsein ist unschädlich, wenn B bei verkehrsüblicher Sorgfalt hätte erkennen können, dass sein Verhalten als Erklärung verstanden wird, und der Empfänger es auch so verstanden hat.", "B kann analog § 119 I Alt. 2 anfechten und schuldet dann Vertrauensschaden (§ 122). Hätte K das Grüßen erkannt, entfiele § 122 (§ 122 II)."], "o": [null, null, null, null, null, null]}, "V-1": {"k": "Nein, M musste das", "w": ["Kündigung = empfangsbedürftige Willenserklärung → wirksam mit Zugang (§ 130 I 1).", "Der Benachrichtigungsschein ist nicht die Erklärung; das Schreiben bleibt bei der Post. Zugang erst mit Abholung.", "Eine Abholpflicht besteht nicht. Treuwidrige Zugangsvereitelung (§ 242) nur, wenn M mit einer rechtserheblichen Erklärung rechnen musste – das tat er nicht.", "Ergebnis: nicht zugegangen; V muss erneut (z. B. per Einwurf-Einschreiben oder Bote) zustellen."], "o": [null, null, null, null, null, null]}, "V-2": {"k": "Ja, das Angebot wa", "w": ["Zugang des Angebots: E-Mail am Freitag um 16 Uhr, innerhalb der Geschäftszeit → noch am Freitag zugegangen.", "Ab Zugang ist H gebunden (§ 145), bis Montag (§ 148). Ein Widerruf wirkt nur, wenn er vorher oder gleichzeitig zugeht (§ 130 I 2) → der Widerruf vom Samstag ist wirkungslos.", "Gs Annahme geht innerhalb der Bindefrist zu → Vertrag geschlossen."], "o": [null, null, null, null, null, null]}, "V-3": {"k": "Nein, es liegt ein", "w": ["Auslegung (§§ 133, 157): „Dollar“ ist objektiv mehrdeutig; laut Sachverhalt keine Klärung möglich.", "Beide glauben sich einig, meinen aber Verschiedenes → versteckter Dissens (§ 155).", "Die Währung bestimmt den Preis = wesentlicher Punkt; ohne Einigung hätten sie nicht geschlossen → kein Vertrag."], "o": [null, null, null, null, null, null]}, "fb-2-vs3": {"k": "1, 3 und 4", "w": ["Beide sind Kaufleute (GmbH, e. K.) → Regeln zum kaufmännischen Bestätigungsschreiben (§ 346 HGB).", "S schweigt auf das zeitnah zugegangene Schreiben → es gilt sein Inhalt (Aussage 1). „Abholung ab Lager“ entspricht ohnehin der gesetzlichen Holschuld (§ 269) → S muss abholen (Aussage 3).", "Grenze: Wer bewusst etwas anderes bestätigt als vereinbart, ist nicht schutzwürdig (Aussage 4). Für Verbraucher gelten die Regeln nicht (Aussage 5 falsch).", "Richtig: 1, 3 und 4."], "o": [null, null, null, null, null, null]}, "L1-5": {"k": "Kein Vertrag: Das ", "w": ["Schaufensterauslage = invitatio ad offerendum: H will sich nicht gegenüber jedermann binden (Vorrat, Fehler).", "Ks Erklärung an der Kasse ist das Angebot zu 49 €. Die Verkäuferin lehnt ab → kein Vertrag.", "Ohne Vertrag gibt es nichts anzufechten und deshalb auch keinen Vertrauensschaden nach § 122 (Fahrtkosten).", "Die Preisangabenverordnung ist öffentliches Recht und begründet keinen Vertrag."], "o": [null, null, null, null, null, null]}, "L1-6": {"k": "Nein, der Widerruf", "w": ["Zugang des Angebots (§ 130 I 1): Einwurf Freitag 19 Uhr nach Geschäftsschluss → mit Kenntnisnahme ist erst Montag 8 Uhr zu rechnen.", "Widerruf am Samstag telefonisch gegenüber dem Geschäftsführer: unter Anwesenden → sofort zugegangen. Der Geschäftsführer vertritt die GmbH auch passiv (§ 35 GmbHG, § 164 III), egal über welches Telefon.", "Der Widerruf ging vor dem Angebot zu (§ 130 I 2) → das Angebot wurde nie wirksam → kein Vertrag."], "o": [null, null, null, null, null, null]}, "L1-7": {"k": "Nein: Die erste An", "w": ["Vs Angebot zu 8.000 € mit Annahmefrist.", "Ks erste Antwort ändert Preis und Umfang → Ablehnung verbunden mit neuem Angebot (§ 150 II). Damit erlischt Vs Angebot (§ 146) – auch wenn die Frist noch läuft.", "Ks zweite Erklärung „zu 8.000 €“ ist deshalb keine Annahme, sondern ein neues Angebot, das V nicht annimmt → kein Vertrag."], "o": [null, null, null, null, null, null]}, "L1-8": {"k": "Ansprüche des U ge", "w": ["Unbestellte Ware eines Unternehmers an eine Verbraucherin → § 241a I: Es werden keine Ansprüche gegen den Verbraucher begründet.", "Kein Vertrag: Benutzen ist nach h. M. keine Annahme; eine Fristsetzung kann Schweigen nicht zur Annahme machen.", "Gesperrt sind auch gesetzliche Ansprüche: Herausgabe (§ 985) und Wertersatz (§§ 812, 818 II). V darf das Parfum behalten und nutzen."], "o": [null, null, null, null, null, null]}, "L1-9": {"k": "Ja, auch wer ohne ", "w": ["Kein Vertrag nötig: Die Auslobung (§ 657) ist ein einseitiges Rechtsgeschäft; der Anspruch entsteht durch die Handlung.", "Auf Kenntnis kommt es nicht an (§ 657 a. E.).", "Minderjährigkeit schadet nicht: F muss keine Willenserklärung abgeben; der Erwerb des Anspruchs ist zudem lediglich rechtlich vorteilhaft (§ 107).", "F erhält 50 €."], "o": [null, null, null, null, null, null]}});
